//! `cargo xtask encodings-gen [--check]`: generate the tables of the built-in multi-byte `iconv`
//! codecs from the WHATWG Encoding Standard indexes in `spec/encoding/whatwg` (CC BY 4.0; see its
//! README.md).
//!
//! Generated file: `crates/core/src/iconv/jis_tables.rs`: JIS X 0208 and JIS X 0212 as 94 x 94
//! arrays by pointer (`row * 94 + cell`, 0 = unassigned) and, for encoding, each set's code points
//! in ascending order with the pointer of each (equal code points by ascending pointer). Pointers
//! beyond 94 x 94 (the index's extension area, used by Shift_JIS only) are left out. The tables
//! carry the indexes unchanged: a codec's variant rules (rows it accepts, cells it maps
//! differently) live in the codec. With `--check`, nothing is written; the command fails if the
//! file would change.

use std::fmt::Write as _;
use std::fs;
use std::path::Path;

const OUT: &str = "crates/core/src/iconv/jis_tables.rs";
const CELLS: usize = 94 * 94;

/// The index file `name`: (pointer, code point) pairs below [`CELLS`], each a BMP code point.
fn index(root: &Path, name: &str) -> Result<Vec<(usize, u16)>, String> {
    let path = root.join("spec/encoding/whatwg").join(name);
    let text = fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    let mut out = Vec::new();
    for (k, line) in text.lines().enumerate() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut f = line.split('\t').map(str::trim);
        let bad = || format!("{name}:{}: not `pointer<TAB>0xCODE`", k + 1);
        let p: usize = f.next().ok_or_else(bad)?.parse().map_err(|_| bad())?;
        let cp = f.next().and_then(|s| s.strip_prefix("0x")).ok_or_else(bad)?;
        let cp = u32::from_str_radix(cp, 16).map_err(|_| bad())?;
        if p >= CELLS {
            continue;
        }
        let cp = u16::try_from(cp).ok().filter(|&c| c != 0).ok_or_else(|| format!("{name}:{}: code point outside the BMP or zero", k + 1))?;
        out.push((p, cp));
    }
    Ok(out)
}

fn array(w: &mut String, doc: &str, name: &str, values: &[u16]) {
    let _ = writeln!(w, "/// {doc}\npub(super) static {name}: [u16; {}] = [", values.len());
    for row in values.chunks(16) {
        let _ = writeln!(w, "    {},", row.iter().map(|v| format!("0x{v:04X}")).collect::<Vec<_>>().join(", "));
    }
    w.push_str("];\n\n");
}

/// One set: its decode array and its encode pair of arrays.
fn set(w: &mut String, root: &Path, file: &str, set: &str, ident: &str) -> Result<(), String> {
    let pairs = index(root, file)?;
    let mut by_ptr = vec![0u16; CELLS];
    for &(p, cp) in &pairs {
        if let Some(slot) = by_ptr.get_mut(p) {
            if *slot != 0 {
                return Err(format!("{file}: pointer {p} listed twice"));
            }
            *slot = cp;
        }
    }
    let mut by_cp: Vec<(u16, u16)> = pairs.iter().map(|&(p, cp)| (cp, u16::try_from(p).unwrap_or(u16::MAX))).collect();
    by_cp.sort_unstable();
    array(w, &format!("{set}: the code point of each pointer (`row * 94 + cell`, rows and cells from 0), 0 for none."), ident, &by_ptr);
    let cps: Vec<u16> = by_cp.iter().map(|x| x.0).collect();
    let ptrs: Vec<u16> = by_cp.iter().map(|x| x.1).collect();
    array(w, &format!("{set}: the code points it has, ascending (a code point listed twice appears twice)."), &format!("{ident}_CPS"), &cps);
    array(w, &format!("{set}: the pointer of each entry of `{ident}_CPS`."), &format!("{ident}_PTRS"), &ptrs);
    Ok(())
}

fn generate(root: &Path) -> Result<String, String> {
    let mut w = String::new();
    w.push_str("// @generated by `cargo xtask encodings-gen` from spec/encoding/whatwg (index-jis0208.txt,\n");
    w.push_str("// index-jis0212.txt of the WHATWG Encoding Standard, https://encoding.spec.whatwg.org/, by\n");
    w.push_str("// WHATWG (Apple, Google, Mozilla, Microsoft), CC BY 4.0). Do not edit: xtask/src/encodings.rs.\n");
    w.push_str("#![allow(clippy::unreadable_literal)]\n\n");
    set(&mut w, root, "index-jis0208.txt", "JIS X 0208", "JIS0208")?;
    set(&mut w, root, "index-jis0212.txt", "JIS X 0212", "JIS0212")?;
    while w.ends_with("\n\n") {
        w.pop();
    }
    Ok(w)
}

pub fn run(root: &Path, check: bool) -> Result<(), String> {
    let text = generate(root)?;
    let path = root.join(OUT);
    if check {
        let have = fs::read_to_string(&path).map_err(|e| format!("{OUT}: {e}"))?;
        if have != text {
            return Err(format!("{OUT} is stale: run `cargo xtask encodings-gen`"));
        }
        println!("encodings-gen: {OUT} is current");
        return Ok(());
    }
    fs::write(&path, text).map_err(|e| format!("{OUT}: {e}"))?;
    println!("encodings-gen: wrote {OUT}");
    Ok(())
}
